diff --git a/apps/web/src/components/ride/OfficialCourseListModal.css b/apps/web/src/components/ride/OfficialCourseListModal.css
index b922ad3..afa92f8 100644
--- a/apps/web/src/components/ride/OfficialCourseListModal.css
+++ b/apps/web/src/components/ride/OfficialCourseListModal.css
@@ -271,3 +271,110 @@
   justify-content: flex-end;
   margin: 0 0 0.45rem;
 }
+
+/* ── 지시23: 퍼블릭 경로 목록 한정 (입문/내 경로·모달 기본 불변) ── */
+
+/* 1. 퍼블릭이 든 창만 넓게·높게. 0/1/2/빈/로딩은 내용 높이, 많으면 상한까지. */
+.oc-modal-overlay:has(.oc-modal[aria-label="퍼블릭 경로"]) {
+  padding: 8px;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] {
+  position: relative;
+  width: min(560px, calc(100vw - 16px));
+  max-height: calc(100vh - 16px);
+  max-height: calc(100dvh - 16px);
+}
+
+/* 4. 상단 여백 절제 — 퍼블릭 창에만. 폰트·버튼 높이/패딩 불변, 닫기 자리(우 2.4rem) 유지. */
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__head {
+  padding: 0.5rem 2.4rem 0.5rem 0.65rem;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__body {
+  padding: 0.5rem 0.6rem 0.6rem;
+}
+
+/* 2. 정렬 바를 헤더 한 행 안에 absolute. 닫기(우 0.3rem·폭 1.9rem)와 겹치지 않게 우 2.4rem. */
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__sortbar {
+  position: absolute;
+  top: 0;
+  right: 2.4rem;
+  height: 3rem;
+  margin: 0;
+  display: flex;
+  align-items: center;
+  justify-content: flex-end;
+  white-space: nowrap;
+}
+
+/* 정렬 바가 있을 때만 검색 오른쪽을 정렬 폭만큼 비운다. 0/1/2개(정렬 없음)는 예약 없음. */
+.oc-modal[aria-label="퍼블릭 경로"]:has(.oc-modal__sortbar) .oc-modal__search {
+  margin-right: 6.5rem;
+}
+
+/* 3. 내 경로와 같이 행 구분선·gap 절제. 카드 테두리/둥근 반복 제거. */
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__list {
+  gap: 0;
+  border-top: 1px solid #E2E8F0;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__item {
+  border: none;
+  border-bottom: 1px solid #E2E8F0;
+  border-radius: 0;
+  background: transparent;
+  box-sizing: border-box;
+  min-height: 32px;
+  height: auto;
+  padding: 1px 0.55rem;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__item:hover:not(:disabled) {
+  background: #EFF6FF;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__item.is-selected {
+  background: #EFF6FF;
+  box-shadow: inset 3px 0 0 0 #2563EB;
+}
+
+/* 이름 전체 유지·줄바꿈으로 가로 overflow 방지. 축약/재작성/line-clamp 없음.
+   지시25: 행 밀도용 line-height만 퍼블릭 범위에서 1.2로 (공용 base 불변). */
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__item-name {
+  line-height: 1.15;
+  overflow-wrap: anywhere;
+  word-break: break-word;
+}
+
+/* 긴 등록자 이름은 메타 안에서 줄바꿈으로 가로 overflow 방지. 숨김으로 해결하지 않음.
+   지시25: sub 상단 간격·행간만 퍼블릭 범위에서 절제 (공용 base 불변). */
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__item-sub {
+  flex-wrap: wrap;
+  row-gap: 0.1rem;
+  margin-top: 0;
+  line-height: 1.15;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__item-publisher {
+  flex-shrink: 1;
+  min-width: 0;
+  white-space: normal;
+  overflow-wrap: anywhere;
+  word-break: break-word;
+  text-align: right;
+}
+
+/* 4. 긴 오류는 본문 스크롤 예외로 전체 접근, 헤더(본문 밖) 고정. 일반 상태는 목록만 스크롤. */
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__body:has(.oc-modal__error) {
+  overflow-x: hidden;
+  overflow-y: auto;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__error {
+  flex-shrink: 0;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__error-detail {
+  overflow-wrap: anywhere;
+}
